option.value:
.counter {
  font-size: 16px;
  padding: 5px 10px;
  border-radius: 5px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 2px solid transparent;
  transition: border-color 0.3s;
  margin-bottom: 24px;

  &:hover {
    border-color: var(--accent-border);
  }
  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.hero {
  position: relative;

  .base,
  .framework,
  .vite {
    inset-inline: 0;
    margin: 0 auto;
  }

  .base {
    width: 170px;
    position: relative;
    z-index: 0;
  }

  .framework,
  .vite {
    position: absolute;
  }

  .framework {
    z-index: 1;
    top: 34px;
    height: 28px;
    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)
      scale(1.4);
  }

  .vite {
    z-index: 0;
    top: 107px;
    height: 26px;
    width: auto;
    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)
      scale(0.8);
  }
}

#center {
  display: flex;
  flex-direction: column;
  gap: 25px;
  place-content: center;
  place-items: center;
  flex-grow: 1;

  @media (max-width: 1024px) {
    padding: 32px 20px 24px;
    gap: 18px;
  }
}

#next-steps {
  display: flex;
  border-top: 1px solid var(--border);
  text-align: left;

  & > div {
    flex: 1 1 0;
    padding: 32px;
    @media (max-width: 1024px) {
      padding: 24px 20px;
    }
  }

  .icon {
    margin-bottom: 16px;
    width: 22px;
    height: 22px;
  }

  @media (max-width: 1024px) {
    flex-direction: column;
    text-align: center;
  }
}

#docs {
  border-right: 1px solid var(--border);

  @media (max-width: 1024px) {
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
}

#next-steps ul {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 8px;
  margin: 32px 0 0;

  .logo {
    height: 18px;
  }

  a {
    color: var(--text-h);
    font-size: 16px;
    border-radius: 6px;
    background: var(--social-bg);
    display: flex;
    padding: 6px 12px;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    transition: box-shadow 0.3s;

    &:hover {
      box-shadow: var(--shadow);
    }
    .button-icon {
      height: 18px;
      width: 18px;
    }
  }

  @media (max-width: 1024px) {
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;

    li {
      flex: 1 1 calc(50% - 8px);
    }

    a {
      width: 100%;
      justify-content: center;
      box-sizing: border-box;
    }
  }
}

#spacer {
  height: 88px;
  border-top: 1px solid var(--border);
  @media (max-width: 1024px) {
    height: 48px;
  }
}

.ticks {
  position: relative;
  width: 100%;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: -4.5px;
    border: 5px solid transparent;
  }

  &::before {
    left: 0;
    border-left-color: var(--border);
  }
  &::after {
    right: 0;
    border-right-color: var(--border);
  }
}

/* Additional styles for the cybersecurity landing page */
.hero-section {
  background: linear-gradient(180deg, rgba(250,250,252,0.6), rgba(255,255,255,0));
}
.hero-image {
  max-width: 380px;
  box-shadow: var(--shadow);
}

section#whoami, section#blog, section#contact {
  padding-top: 48px;
  padding-bottom: 48px;
}

.card {
  border: 1px solid var(--border);
  border-radius: 8px;
}

footer {
  border-top: 1px solid var(--border);
  background-color: var(--bg);
}

footer small {
  color: var(--text);
}

@media (max-width: 768px) {
  .hero-image {
    max-width: 260px;
  }
  h1.display-5 {
    font-size: 28px;
  }
}

/* Layout tweaks */
main {
  min-height: calc(100vh - 160px);
}

.navbar {
  background: rgba(255,255,255,0.9);
}

.hero-section {
  background: linear-gradient(180deg, rgba(250,250,252,0.6), rgba(255,255,255,0));
  padding-top: 56px;
  padding-bottom: 56px;
}

h2 {
  margin-top: 8px;
  margin-bottom: 8px;
}

ul {
  padding-left: 1.2rem;
}

.card {
  border: 1px solid var(--border);
  border-radius: 8px;
}

.lead {
  color: var(--text);
}

/* Page transition styles */
.page-view {
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 260ms ease, transform 260ms ease;
}
.page-view.visible {
  opacity: 1;
  transform: none;
}

/* make headings focus-visible when programmatically focused */
#page-heading:focus {
  outline: 3px solid rgba(34,139,230,0.25);
  outline-offset: 4px;
}

